public class LetterShifter {

    public static char shiftLetter(char c, int shift) {
        if (c < 'a' || c > 'z') {
            return c;
        }
        int position = c - 'a';
        int shifted = (position + shift) % 26;
        return (char) ('a' + shifted);
    }
}
